fn finish(){assert_eq!(read(r("runs/result.json"))["status"],"complete");for(p,h)in read(r("pins.json")).as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());}let prior=read(r("prior-proof-sha256.json"));let mut ledger=prior.as_array().unwrap().iter().map(|v|v.as_str().unwrap().to_owned()).collect::<BTreeSet<_>>();assert_eq!(ledger.len(),29255);let jobs=read(r("jobs.json"));let mut inventory=Vec::new();let mut rows=BTreeMap::<String,Vec<Value>>::new();let mut total_calls=0;let mut epoch_count=0;for j in jobs.as_array().unwrap(){let n=j["name"].as_str().unwrap();let v=parse(j);total_calls+=j["rounds"].as_u64().unwrap()+3;epoch_count+=v["epochs"].as_array().unwrap().len();let c=&j["case"];let dir=Path::new(j["proof_directory"].as_str().unwrap());let proof=dir.join("0.proof");let public=dir.join("0.public");assert_eq!(fs::metadata(&proof).unwrap().len(),164);let ph=hash(&proof);let wh=hash(&public);assert_eq!(wh,c["public_sha256"]);assert!(ledger.insert(ph.clone()),"proof must be new acrossall campaigns");let output=fs::read_to_string(r(format!("runs/verify-{n}/stdout.log"))).unwrap();let line=output.lines().filter(|s|s.starts_with("VERIFIED proof_sha256=")).collect::<Vec<_>>();assert_eq!(line.len(),1);let fields=line[0].split_whitespace().skip(1).map(|s|s.split_once('=').unwrap()).collect::<BTreeMap<_,_>>();assert_eq!(fields["proof_sha256"],ph);assert_eq!(fields["public_sha256"],wh);assert_eq!(fields["image_sha256"],c["image_sha256"]);assert_eq!(fields["vk_sha256"],c["vk_sha256"]);inventory.push(json!({"name":n,"proof_sha256":ph,"public_sha256":wh,"image_sha256":c["image_sha256"],"vk_sha256":c["vk_sha256"],"verified":true}));if j["phase"]=="latency"{rows.entry(format!("{}/{}",c["name"].as_str().unwrap(),j["arm"].as_str().unwrap())).or_default().push(json!({"block":j["block"],"name":n,"result":v}));}}
 assert_eq!(total_calls,6168);assert_eq!(epoch_count,1864);assert_eq!(inventory.len(),192);assert_eq!(ledger.len(),29447);let mut pairs=BTreeMap::new();let mut checks=BTreeMap::new();let mut cells=BTreeMap::new();let mut timings=BTreeMap::new();for c in read(r("cases.json")).as_array().unwrap(){let ctx=c["name"].as_str().unwrap();for arm in ARMS{let rr=&rows[&format!("{ctx}/{arm}")];assert_eq!(rr.len(),15);for(i,r)in rr.iter().enumerate(){assert_eq!(r["block"],i);}cells.insert(format!("{ctx}/{arm}"),json!({"median_ms":median(rr.iter().map(|r|r["result"]["median_ms"].as_f64().unwrap()).collect()),"blocks":rr}));}for(a,b)in[("OFF","accepted"),("ON","OFF"),("ON","accepted")]{let ratios=(0..15).map(|i|rows[&format!("{ctx}/{a}")][i]["result"]["median_ms"].as_f64().unwrap()/rows[&format!("{ctx}/{b}")][i]["result"]["median_ms"].as_f64().unwrap()).collect::<Vec<_>>();let s=rank(&ratios);let pass=if a=="OFF"{s["low"].as_f64().unwrap()>=1./1.03&&s["high"].as_f64().unwrap()<=1.03}else{s["high"].as_f64().unwrap()<=1.03};let k=format!("{ctx}/{a}/{b}");checks.insert(k.clone(),pass);pairs.insert(k,s);}
 let samples=rows[&format!("{ctx}/ON")].iter().flat_map(|r|r["result"]["epochs"].as_array().unwrap().iter()).collect::<Vec<_>>();assert_eq!(samples.len(),465);let mut stages=Vec::new();for e in 0..=16{let cumulative=samples.iter().map(|s|s["elapsed_ns"][e].as_u64().unwrap()as f64).collect::<Vec<_>>();let remaining=samples.iter().map(|s|(s["elapsed_ns"][16].as_u64().unwrap()-s["elapsed_ns"][e].as_u64().unwrap())as f64).collect::<Vec<_>>();stages.push(json!({"epochs_completed":e,"cumulative_median_ns":median(cumulative.clone()),"cumulative_min_ns":cumulative.iter().copied().fold(f64::INFINITY,f64::min),"cumulative_max_ns":cumulative.iter().copied().fold(0.,f64::max),"remaining_solver_median_ns":median(remaining)}));}timings.insert(ctx.to_owned(),json!({"snapshots":465,"stage_descriptive_stats":stages,"ready_counts_source":format!("/home/ubuntu/src/zopro-perf-work/parallel-readiness176/{}.json",c["shape"].as_str().unwrap()),"no_elapsed_to_removable_wall_claim":true}));}
 let failed=checks.iter().filter(|(_,v)|!**v).map(|(k,_)|k.clone()).collect::<Vec<_>>();let a=json!({"complete":true,"observer_overhead_screen_passed":failed.is_empty(),"failed_checks":failed,"checks":checks,"pairs":pairs,"cells":cells,"epoch_timing":timings,"SDK_requests":6168,"exports":192,"new_Gnark_exports":192,"clock_snapshots":1864,"prior_ledger":29255,"proof_ledger":29447,"production_changed":false,"adopted":false,"goal_achieved":false,"scope":"diagnostic cumulative epoch elapsed, not proof optimization or removabletime"});save(r("analysis.json"),&a);save(r("rows.json"),&json!(rows));save(r("proof-inventory.json"),&json!(inventory));save(r("proof-sha256-after.json"),&json!(ledger));println!("Observercalibration{} failed{};6168SDK/192freshGnark/1864snapshots;ledger29447;notadopted",a["observer_overhead_screen_passed"],a["failed_checks"]);for(k,t)in timings{let s=&t["stage_descriptive_stats"];println!("{k} total={:.3}us first={:.3}us remainingafterfirst={:.3}us",s[16]["cumulative_median_ns"].as_f64().unwrap()/1000.,s[1]["cumulative_median_ns"].as_f64().unwrap()/1000.,s[1]["remaining_solver_median_ns"].as_f64().unwrap()/1000.);}}
